changeSet.sql:
ALTER TABLE app.StaffProfiles DROP CONSTRAINT CK_StaffProfiles_EmploymentType;
ALTER TABLE app.StaffProfiles ADD CONSTRAINT CK_StaffProfiles_EmploymentType
    CHECK (EmploymentType IS NULL OR EmploymentType IN (
        N'FullTime', N'PartTime', N'Contract', N'Temporary', N'Intern', N'Freelance', N'VisitingTrainer'));

rollback.sql:
UPDATE app.StaffProfiles
SET EmploymentType = N'Contract'
WHERE EmploymentType IN (N'Freelance', N'VisitingTrainer');
ALTER TABLE app.StaffProfiles DROP CONSTRAINT CK_StaffProfiles_EmploymentType;
ALTER TABLE app.StaffProfiles ADD CONSTRAINT CK_StaffProfiles_EmploymentType
    CHECK (EmploymentType IS NULL OR EmploymentType IN (N'FullTime', N'PartTime', N'Contract', N'Temporary', N'Intern'));
